    /** Runs one accepted fork or aggregates the exact five retained forks. @param args fork/attempt or {@code aggregate} @throws Throwable on gate or evidence failure */
    public static void main(String[]args)throws Throwable{
        if(args.length>0&&args[0].equals("aggregate")){aggregate();return;}int fork=args.length==0?0:Integer.parseInt(args[0]),attempt=args.length<2?0:Integer.parseInt(args[1]);StringBuilder report=new StringBuilder();
        try(Arena arena=Arena.ofConfined()){environment(report);List<Case>cases=cases(arena);int[]repetitions=new int[cases.size()*2];for(int i=0;i<cases.size();i++){gate(cases.get(i));repetitions[2*i]=repetitions(cases.get(i).generated);repetitions[2*i+1]=repetitions(cases.get(i).direct);}long[][]generated=new long[cases.size()][9],direct=new long[cases.size()][9];Random random=new Random(0x0008_A0260826L^fork*0x9e3779b97f4a7c15L^attempt*0xd1b54a32d192ed03L);for(int round=-5;round<9;round++){List<Integer>order=new ArrayList<>();for(int i=0;i<cases.size();i++)order.add(i);Collections.shuffle(order,random);for(int i:order){long gt,dt;if(random.nextBoolean()){gt=time(cases.get(i).generated,repetitions[2*i]);dt=time(cases.get(i).direct,repetitions[2*i+1]);}else{dt=time(cases.get(i).direct,repetitions[2*i+1]);gt=time(cases.get(i).generated,repetitions[2*i]);}if(round>=0){generated[i][round]=gt/repetitions[2*i];direct[i][round]=dt/repetitions[2*i+1];gate(cases.get(i));}}}int failures=0;for(int i=0;i<cases.size();i++){long gm=median(generated[i]),dm=median(direct[i]);double ratio=(double)gm/dm;if(!(ratio<=1.15))failures++;report.append(String.format(Locale.ROOT,"RESULT,%s,%d,%d,%.9f,%s,%s%n",cases.get(i).name,gm,dm,ratio,Arrays.toString(generated[i]),Arrays.toString(direct[i])));}report.append("SINK,").append(sink).append('\n');if(failures!=0)throw new AssertionError("ratio failures "+failures);}catch(Throwable failure){report.append("REJECTED,").append(failure.getClass().getName()).append(',').append(clean(failure.getMessage())).append('\n');retain(false,fork,attempt,report.toString());System.out.print(report);throw failure;}retain(true,fork,attempt,report.toString());System.out.print(report);
    }

    private static List<Case>cases(Arena arena)throws Throwable{return List.of(f32("CONV3D-DENSE-F32",Shape.of(1,4,10,10,10),Shape.of(8,4,3,3,3),Shape.of(1,8,8,8,8),Conv3dAttrs.defaults(),false,1),f32("CONV3D-GROUPED-BIASED-F32",Shape.of(1,8,9,9,9),Shape.of(8,2,3,3,3),Shape.of(1,8,9,9,9),new Conv3dAttrs(1,1,1,1,1,1,1,1,1,4),true,1),f64(),bf16(),allSegment(arena),mixedGeneral(arena),f32("CONV3D-PARALLEL-F32",Shape.of(2,8,10,10,10),Shape.of(16,8,3,3,3),Shape.of(2,16,8,8,8),Conv3dAttrs.defaults(),false,4));}

    private static Case f32(String name,Shape xs,Shape ws,Shape ys,Conv3dAttrs attrs,boolean bias,int ranges)throws Throwable{List<DataType>types=Collections.nCopies(bias?3:2,DataType.FLOAT32);ExecutionUnitPlan unit=unit(types,xs,ws,ys,attrs,CarrierAccess.FLOAT_ARRAY,ranges);MethodHandle handle=handle(unit);int xc=count(xs),wc=count(ws),yc=count(ys),oc=(int)ws.toLongArray()[0];float[]x=new float[xc],w=new float[wc],b=bias?new float[oc]:null,g=new float[yc],d=new float[yc];fill(x);fill(w);if(b!=null)fill(b);long[]packed=unit.conv3dGeometry().orElseThrow().pack(new long[bias?4:3]);Geometry geometry=new Geometry(xs.toLongArray(),ws.toLongArray(),ys.toLongArray(),attrs);Action generated=()->{for(int r=0;r<ranges;r++){long start=(long)yc*r/ranges,end=(long)yc*(r+1)/ranges;if(bias)handle.invokeExact(x,w,b,g,packed,start,end);else handle.invokeExact(x,w,g,packed,start,end);}return checksum(g);};Action direct=()->{for(int r=0;r<ranges;r++)conv32(geometry,x,w,b,d,(long)yc*r/ranges,(long)yc*(r+1)/ranges);return checksum(d);};return new Case(name,generated,direct,()->{if(!Arrays.equals(g,d))throw new AssertionError(name);});}
