    private static Case bf16()throws Throwable{Shape xs=Shape.of(1,8,8,8,8),ws=Shape.of(8,1,3,3,3),ys=Shape.of(1,8,8,8,8);Conv3dAttrs attrs=new Conv3dAttrs(1,1,1,1,1,1,1,1,1,8);ExecutionUnitPlan unit=unit(Collections.nCopies(2,DataType.BFLOAT16),xs,ws,ys,attrs,CarrierAccess.SHORT_ARRAY,1);MethodHandle handle=handle(unit);short[]x=new short[count(xs)],w=new short[count(ws)],g=new short[count(ys)],d=new short[count(ys)];fill(x);fill(w);long[]packed=unit.conv3dGeometry().orElseThrow().pack(new long[3]);Geometry geometry=new Geometry(xs.toLongArray(),ws.toLongArray(),ys.toLongArray(),attrs);Action generated=()->{handle.invokeExact(x,w,g,packed,0L,(long)g.length);return checksum(g);};Action direct=()->{conv16(geometry,x,w,d,0,d.length);return checksum(d);};return new Case("CONV3D-DEPTHWISE-BF16",generated,direct,()->{if(!Arrays.equals(g,d))throw new AssertionError("bf16");});}

    private static Case allSegment(Arena arena)throws Throwable{
        Shape xs=Shape.of(1,2,8,8,8),ws=Shape.of(3,2,3,3,3),ys=Shape.of(1,3,6,6,6);Conv3dAttrs attrs=Conv3dAttrs.defaults();
        var unit=unit(Collections.nCopies(2,DataType.FLOAT32),xs,ws,ys,attrs,null,List.of(CarrierAccess.MEMORY_SEGMENT,CarrierAccess.MEMORY_SEGMENT,CarrierAccess.MEMORY_SEGMENT),1);
        MethodHandle handle=handle(unit);MemorySegment x=arena.allocate((long)count(xs)*4,4),w=arena.allocate((long)count(ws)*4,4),g=arena.allocate((long)count(ys)*4,4),d=arena.allocate((long)count(ys)*4,4);fill32(x);fill32(w);long[]packed=unit.conv3dGeometry().orElseThrow().pack(new long[3]);Geometry geometry=new Geometry(xs.toLongArray(),ws.toLongArray(),ys.toLongArray(),attrs);
        Action generated=()->{handle.invokeExact(x,w,g,packed,0L,(long)count(ys));return checksum32(g);};Action direct=()->{conv32Segments(geometry,x,w,d,0,count(ys));return checksum32(d);};return new Case("CONV3D-ALL-SEGMENT-F32",generated,direct,()->{if(g.mismatch(d)!=-1)throw new AssertionError("all segment");});
    }

