        var layouts=List.of(LayoutDescriptor.of(xs,new long[]{2600,641,89,10,1},7,true),LayoutDescriptor.of(ws,new long[]{41,19,9,4,2},3,true),LayoutDescriptor.of(ys,new long[]{3600,587,83,9,1},5,true));
        var unit=unit(List.of(DataType.BFLOAT16,DataType.FLOAT64),xs,ws,ys,attrs,layouts,List.of(CarrierAccess.MEMORY_SEGMENT,CarrierAccess.DOUBLE_ARRAY,CarrierAccess.MEMORY_SEGMENT),1);var boundaries=unit.conv3dGeometry().orElseThrow().boundaries();MethodHandle handle=handle(unit);MemorySegment x=arena.allocate(span(boundaries.get(0))*2,2),g=arena.allocate(span(boundaries.get(2))*8,8),d=arena.allocate(span(boundaries.get(2))*8,8);double[]w=new double[Math.toIntExact(span(boundaries.get(1)))];fill16(x);fill(w);long[]packed=unit.conv3dGeometry().orElseThrow().pack(new long[3]);
