    private static ExecutionUnitPlan unit(List<DataType>types,Shape x,Shape w,Shape y,Conv3dAttrs attrs,CarrierAccess carrier,int ranges){PrepareContext<CpuPartitionAnalysisInputs>base=CpuConv3dLoweringTest.context(types,x,w,y,attrs,null);var config=new CpuPartitionAnalysisInputs.PortableExecutionConfig(CpuPartitionAnalysisInputs.PortableExecutionConfig.ComputePreference.SCALAR,ranges,ranges,1);var context=new PrepareContext<>(base.partition(),base.nodes(),base.values(),base.memoryRequirements(),base.constants(),new CpuPartitionAnalysisInputs(false,Collections.nCopies(types.size()+1,carrier),config));return new CpuPartitionPreparer().analyze(context).plan().units().getFirst();}
    private static ExecutionUnitPlan unit(List<DataType>types,Shape x,Shape w,Shape y,Conv3dAttrs attrs,List<LayoutDescriptor> layouts,List<CarrierAccess> carriers,int ranges){PrepareContext<CpuPartitionAnalysisInputs>base=CpuConv3dLoweringTest.context(types,x,w,y,attrs,layouts);var config=new CpuPartitionAnalysisInputs.PortableExecutionConfig(CpuPartitionAnalysisInputs.PortableExecutionConfig.ComputePreference.SCALAR,ranges,ranges,1);var context=new PrepareContext<>(base.partition(),base.nodes(),base.values(),base.memoryRequirements(),base.constants(),new CpuPartitionAnalysisInputs(false,carriers,config));return new CpuPartitionPreparer().analyze(context).plan().units().getFirst();}
